def migrate_data(apps, schema_editor):
    import hashlib
    import re

    db = schema_editor.connection.alias
    P = apps.get_model("leasefit", "Premises")
    R = apps.get_model("leasefit", "ClientRequest")
    L = apps.get_model("leasefit", "RequestPremises")
    E = apps.get_model("leasefit", "Evaluation")
    A = apps.get_model("leasefit", "Attachment")
    C = apps.get_model("leasefit", "Characteristic")
    Q = apps.get_model("leasefit", "Requirement")
    O = apps.get_model("leasefit", "Observation")
    agencies = dict(R.objects.using(db).values_list("id", "agency_id"))
    invalid = [
        p.pk for p in P.objects.using(db).all() if not agencies.get(p.request_id)
    ]
    if invalid:
        raise RuntimeError(
            "Cannot determine agency for premises IDs: "
            + str(invalid)
            + ". Migration rolled back. Restore the explicit request/agency mapping; no fallback agency is assigned."
        )

    def norm(s):
        return re.sub(r"\s+", " ", s.strip().casefold().replace("ё", "е"))

    aliases = {}
    for spec in FROZEN_STANDARD:
        C.objects.using(db).get_or_create(
            code=spec["code"],
            defaults={
                k: v for k, v in spec.items() if k not in ["code", "aliases", "primary"]
            },
        )
        for name in [spec["label"], *spec["aliases"]]:
            aliases[norm(name)] = spec["code"]

    def characteristic(agency, name, unit, kind):
        unit = unit_aliases.get(unit.casefold(), unit)
        code = aliases.get(norm(name))
        if code:
            return C.objects.using(db).get(code=code)
        existing = C.objects.using(db).filter(
            agency_id=agency, label__iexact=name, unit=unit
        )
        if existing.count() == 1:
            return existing.first()
        code = (
            "custom_"
            + str(agency)
            + "_"
            + hashlib.sha256(f"{norm(name)}|{unit}|{kind}".encode()).hexdigest()[:20]
        )
        return C.objects.using(db).get_or_create(
            code=code,
            defaults={
                "agency_id": agency,
                "label": name,
                "unit": unit,
                "value_type": kind,
                "group": "custom",
                "allowed_operators": ["gte", "lte", "range", "eq"]
                if kind == "number"
                else ["eq"],
            },
        )[0]

    unit_aliases = {"m2": "м²", "м2": "м²", "kw": "кВт", "квт": "кВт", "m": "м"}
    for p in P.objects.using(db).all().iterator():
        agency = agencies[p.request_id]
        P.objects.using(db).filter(pk=p.pk).update(agency_id=agency)
        link, _ = L.objects.using(db).get_or_create(
            request_id=p.request_id,
            premises_id=p.pk,
            defaults={
                "adaptation": p.adaptation,
                "other_once": p.other_once,
                "stress": p.stress,
                "assumptions": p.assumptions,
                "internal_notes": p.internal_notes,
            },
        )
        E.objects.using(db).filter(premises_id=p.pk).update(
            request_id=p.request_id, link_identity=link.pk
        )
        A.objects.using(db).filter(premises_id=p.pk).update(
            origin_request_id=p.request_id
        )
    for q in Q.objects.using(db).all().iterator():
        c = characteristic(
            agencies[q.request_id],
            q.name,
            q.unit,
            "boolean" if q.operator == "eq" else "number",
        )
        unit = unit_aliases.get(q.unit.casefold(), q.unit)
        Q.objects.using(db).filter(pk=q.pk).update(characteristic_id=c.pk, unit=unit)
    property_agencies = dict(P.objects.using(db).values_list("id", "agency_id"))
    for o in O.objects.using(db).all().iterator():
        c = characteristic(
            property_agencies[o.premises_id],
            o.name,
            o.unit,
            "number"
            if o.value is not None
            else "boolean"
            if o.boolean is not None
            else "text",
        )
        unit = unit_aliases.get(o.unit.casefold(), o.unit)
        O.objects.using(db).filter(pk=o.pk).update(characteristic_id=c.pk, unit=unit)


def reverse_empty_catalog(apps, schema_editor):
    from django.db.migrations.exceptions import IrreversibleError

    if (
        apps.get_model("leasefit", "Premises")
        .objects.using(schema_editor.connection.alias)
        .exists()
    ):
        raise IrreversibleError(
            "A populated shared catalog cannot be reduced to one request per property safely. Restore the verified pre-upgrade backup instead."
        )


